body.script:
function showList(){
    document.getElementById("list_sec").style.display="block";
    document.getElementById("manual_sec").style.display="none";
    document.getElementById("btn_list").classList.add("active");
    document.getElementById("btn_manual").classList.remove("active");
}
function showManual(){
    document.getElementById("list_sec").style.display="none";
    document.getElementById("manual_sec").style.display="block";
    document.getElementById("btn_manual").classList.add("active");
    document.getElementById("btn_list").classList.remove("active");
}
function syncCompany(sel){
    document.getElementById("company_id_hidden").value = sel.value;
    var opt = sel.options[sel.selectedIndex];
    document.getElementById("company_name_hidden").value = opt.getAttribute("data-name") || "";
}

var stepMap = {
    'amendment_legal_type': 'Legal Type',
    'amendment_business_activities': 'Business Activities',
    'amendment_capital_structure': 'Shareholder Information',
    'amendment_shareholder': 'Shareholder Information',
    'amendment_manager': 'Manager Information',
    'amendment_director': 'Director Information',
    'amendment_company_info': 'Company Information',
    'amendment_facility_type': 'Facility Type',
};

function toggleFormationPackage(cb){
    var sec = document.getElementById('formation_package_section');
    if(sec) sec.style.display = cb.checked ? 'block' : 'none';
}

function updateSteps(){
    var checks = document.querySelectorAll('input[type=checkbox][name^="amendment_"]');
    var steps = [];
    var seen = {};
    checks.forEach(function(c){
        if(c.checked && stepMap[c.name] && !seen[stepMap[c.name]]){
            seen[stepMap[c.name]] = true;
            steps.push(stepMap[c.name]);
        }
    });
    var tags = document.getElementById('step_tags');
    if(tags){
        tags.innerHTML = steps.length ? steps.map(function(s){
            return '
+ ' + s + '';
        }).join('') : '
No extra steps';
    }
    document.getElementById('selected_steps_hidden').value = steps.join(',');
}

document.querySelectorAll('input[type=checkbox][name^="amendment_"]').forEach(function(c){
    c.addEventListener('change', updateSteps);
});
updateSteps();

function showFiles(inp){
    var list = document.getElementById("file_list");
    list.innerHTML = "";
    for(var i=0;i<inp.files.length;i++){
        var div = document.createElement("div");
        div.className = "uploaded-item";
        div.innerHTML = "📄 " + inp.files[i].name;
        list.appendChild(div);
    }
}

function selectCard(el, val){
    document.querySelectorAll('.type-card').forEach(function(c){c.classList.remove('selected')});
    el.classList.add('selected');
    el.querySelector('input').checked = true;
}

var selected = {};
function updateSelected(){
    var checks = document.querySelectorAll('#activity_list input[type=checkbox]');
    selected = {};
    checks.forEach(function(c){ if(c.checked) selected[c.value] = c.getAttribute('data-name'); });
    var list = document.getElementById('selected_list');
    var ids = Object.keys(selected);
    if(ids.length === 0){
        list.innerHTML = 'No activity selected yet.';
    } else {
        list.innerHTML = ids.map(function(id){
            return '' + selected[id] + '✕';
        }).join('');
    }
    document.getElementById('activity_ids_hidden').value = ids.join(',');
    document.getElementById('activity_names_hidden').value = Object.values(selected).join(',');
}
function deselect(id){
    var chk = document.querySelector('#activity_list input[value="'+id+'"]');
    if(chk){ chk.checked = false; updateSelected(); }
}
function filterCat(cat, btn){
    document.querySelectorAll('.tab-btn').forEach(function(b){ b.classList.remove('active'); });
    btn.classList.add('active');
    document.querySelectorAll('.activity-item').forEach(function(item){
        item.style.display = (cat === 'all' || item.getAttribute('data-cat') === cat) ? '' : 'none';
    });
}
function filterActivities(q){
    q = q.toLowerCase();
    document.querySelectorAll('.activity-item').forEach(function(item){
        item.style.display = item.getAttribute('data-name').toLowerCase().includes(q) ? '' : 'none';
    });
}
